export default {"html":"<p data-line=\"0\" class=\"code-line\">Instagram, Facebook, and X all offer photo editing, so photo editing in mobile and web apps is commonplace now.</p>\n<p data-line=\"2\" class=\"code-line\">In the browser, rolling your own means image-processing knowledge—and a tough fight with Canvas. Popular, well-built libraries exist; TUI Image Editor is the standout, but its default desktop and mobile UI is hard to match to your app's look.</p>\n<p data-line=\"4\" class=\"code-line\">◯ Desktop UI<br style=\"display:none\">\n<a href=\"https://nhn.github.io/tui.image-editor/latest/examples/example01-includeUi.html\" rel=\"noopener noreferrer\" target=\"_blank\">https://nhn.github.io/tui.image-editor/latest/examples/example01-includeUi.html</a><a href=\"https://nhn.github.io/tui.image-editor/latest/examples/example01-includeUi.html\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://nhn.github.io/tui.image-editor/latest/examples/example01-includeUi.html</a></p>\n<p data-line=\"7\" class=\"code-line\">◯ Mobile UI<br style=\"display:none\">\n<a href=\"https://nhn.github.io/tui.image-editor/latest/examples/example03-mobile.html\" rel=\"noopener noreferrer\" target=\"_blank\">https://nhn.github.io/tui.image-editor/latest/examples/example03-mobile.html</a><a href=\"https://nhn.github.io/tui.image-editor/latest/examples/example03-mobile.html\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://nhn.github.io/tui.image-editor/latest/examples/example03-mobile.html</a></p>\n<p data-line=\"10\" class=\"code-line\">So I released a simple Ionic Angular photo-editing library built on the TUI Image Editor API.</p>\n<h2 id=\"demo\" data-line=\"12\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#demo\" aria-hidden=\"true\"></a> Demo</h2>\n<p data-line=\"14\" class=\"code-line\"><a href=\"https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor\" rel=\"noopener noreferrer\" target=\"_blank\">https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor</a><a href=\"https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://rdlabo-ionic-angular-library.netlify.app/main/photo-editor</a></p>\n<p data-line=\"16\" class=\"code-line\">There is a viewer too; tap \"Launch Photo Editor\" first. It pulls free stock images, so startup is a bit slow, but you get crop and rotate, filters, and brightness as shown below.</p>\n<p data-line=\"18\" class=\"code-line\"><img src=\"/images/7aa8c9091cc4b9/8d95db4a59cc84c14b3f02a461bd9ff7.gif\" alt=\"8d95db4a59cc84c14b3f02a461bd9ff7.gif\" class=\"md-img\" loading=\"lazy\"></p>\n<h2 id=\"usage\" data-line=\"20\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#usage\" aria-hidden=\"true\"></a> Usage</h2>\n<p data-line=\"22\" class=\"code-line\">Install in your Ionic Angular project first.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"24\"><span class=\"line\"><span style=\"color:#B392F0\">%</span><span style=\"color:#9ECBFF\"> npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @rdlabo/ionic-angular-photo-editor</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"28\" class=\"code-line\">Then add this to your global styles.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"30\"><span class=\"line\"><span style=\"color:#B392F0\">:root</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-background</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#2a2a2a</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-background-tint</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#414141</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#f0f0f0</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-color-tint</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#dbdbdb</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-primary</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#4d8dff</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-danger</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#f24c58</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  --ion-photo-editor-success</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#2dd55b</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"44\" class=\"code-line\">Styles use CSS variables, so you can theme them. Usage is simple: when opening an Ionic modal, pass photo data (URL or Base64) via <code>ComponentProps</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"46\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { PhotoEditorPage, IPhotoEditorDismiss } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@rdlabo/ionic-angular-photo-editor'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> modal</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.modalCtrl.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    component: PhotoEditorPage,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    componentProps: {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      requireSquare: </span><span style=\"color:#79B8FF\">false</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      value: </span><span style=\"color:#9ECBFF\">'https://picsum.photos/200/300'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      label: {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        save: </span><span style=\"color:#9ECBFF\">'送信'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#a0aab5\">// change '保存' to '送信'</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> modal.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">data</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> modal.</span><span style=\"color:#B392F0\">onWillDismiss</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">IPhotoEditorDismiss</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (data?.value) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(data.value);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})();</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"68\" class=\"code-line\">Set <code>requireSquere</code> to <code>true</code> to require a square crop. <code>label</code> lets you change button labels. See <a href=\"https://github.com/rdlabo-dev/ionic-angular-library/tree/main/projects/photo-editor\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/rdlabo-dev/ionic-angular-library/tree/main/projects/photo-editor</a> for details.</p>\n<h2 id=\"summary\" data-line=\"70\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"72\" class=\"code-line\">I use this library in apps I ship and it has been stable. It is not a fully polished OSS product, so features are limited—but if you want to add photo editing quickly or read reference source, I hope it helps.</p>\n<p data-line=\"74\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"demo","text":"Demo","level":2},{"id":"usage","text":"Usage","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
